graphSearchArguments.gql:
MATCH (org:`Organization`)<-[:`deliveredFor`]-(project:`Project`)<-[r:`contactFor`|`managedProject`|`productOwnerOf`|`sponsors`|`workedOn`]-(person:`Person`)
WHERE org.name = 'Verhaeghe Foods' AND person.name = 'Elien Jacobs'
RETURN DISTINCT project.name AS project_name, 'Yes' AS has_evidence, type(r) AS evidence
UNION DISTINCT
MATCH (org:`Organization`)<-[:`deliveredFor`]-(project:`Project`)
WHERE org.name = 'Verhaeghe Foods'
  AND NOT EXISTS { (person:`Person` WHERE person.name = 'Elien Jacobs')-[:`contactFor`]->(project) }
  AND NOT EXISTS { (person:`Person` WHERE person.name = 'Elien Jacobs')-[:`managedProject`]->(project) }
  AND NOT EXISTS { (person:`Person` WHERE person.name = 'Elien Jacobs')-[:`productOwnerOf`]->(project) }
  AND NOT EXISTS { (person:`Person` WHERE person.name = 'Elien Jacobs')-[:`sponsors`]->(project) }
  AND NOT EXISTS { (person:`Person` WHERE person.name = 'Elien Jacobs')-[:`workedOn`]->(project) }
RETURN DISTINCT project.name AS project_name, 'No' AS has_evidence, NULL AS evidence
